-- Étapes détaillées des recettes communes (végétariennes) (durées, feu, °C, repères de cuisson), pour la fiche « pas à pas » et ses
-- minuteurs. Nouvelle version de chaque recette : la version en cours est recopiée (ingrédients, temps…), seules les étapes
-- changent (data/recipes/seed.json). Idempotent : rien n'est fait si la version portant cette note existe déjà.
do $do$
declare
  r record;
  rid uuid;
  cv public.recipe_versions;
  p jsonb;
begin
  for r in select key as slug, value as steps from jsonb_each($etapes${"dahl-lentilles-corail":["Émincer l'oignon, hacher l'ail et râper le gingembre. Rincer les lentilles corail jusqu'à ce que l'eau soit claire.","Chauffer l'huile à feu moyen dans une cocotte. Faire revenir l'oignon, l'ail et le gingembre avec le curry et le curcuma 3 min, jusqu'à ce que l'oignon soit tendre.","Ajouter les lentilles, les tomates, le lait de coco et 40 cl d'eau, saler. Cuire 20 min à feu doux en remuant souvent pour que ça n'attache pas : les lentilles doivent être fondues.","Pendant ce temps, cuire le riz 11 min dans l'eau bouillante salée et l'égoutter. Servir le dahl parsemé de coriandre."],"curry-pois-chiches-epinards":["Émincer l'oignon, hacher l'ail. Rincer et égoutter les pois chiches.","Chauffer l'huile à feu moyen dans une sauteuse. Faire revenir l'oignon et l'ail avec le curry et le cumin 3 min.","Ajouter les tomates, le lait de coco et les pois chiches, saler et laisser mijoter 12 min à feu doux.","Pendant ce temps, cuire le riz 11 min dans l'eau bouillante salée et l'égoutter.","Incorporer les épinards et remuer 2 min, jusqu'à ce qu'ils tombent. Servir avec le riz."],"chili-sin-carne":["Émincer l'oignon et couper les poivrons en dés. Rincer les lentilles et les haricots rouges.","Chauffer l'huile à feu moyen dans une cocotte. Faire revenir l'oignon et les poivrons 5 min, ajouter le cumin et le paprika et remuer 1 min.","Ajouter les tomates, les lentilles, les haricots et 20 cl d'eau, saler. Laisser mijoter 30 min à feu doux à couvert, en remuant toutes les 10 min.","Ajouter le maïs égoutté 5 min avant la fin. Pendant ce temps, cuire le riz 11 min dans l'eau bouillante salée et servir ensemble."],"salade-lentilles-feta":["Rincer les lentilles et les cuire 20 min dans une grande casserole d'eau non salée, à petits frémissements : elles doivent rester légèrement fermes. Les égoutter et les saler.","Préparer la vinaigrette avec la moutarde, le vinaigre, l'huile et du sel.","Couper les tomates cerises en deux, émincer finement l'oignon rouge, couper la feta en dés et ciseler le persil.","Mélanger les lentilles encore tièdes avec la vinaigrette (elles l'absorbent mieux), puis ajouter les tomates, l'oignon, la feta et le persil."],"wraps-falafels-sauce-yaourt":["Préchauffer le four à 200 °C et réchauffer les falafels 10 min (ou 5 min à la poêle à feu moyen en les retournant).","Mélanger le yaourt, le jus du demi-citron, le cumin et une pincée de sel.","Râper la carotte, couper le concombre en bâtonnets et la tomate en dés, laver la salade.","Garnir les wraps de crudités, de falafels écrasés grossièrement et de sauce, puis rouler serré."],"soupe-lentilles-carottes":["Émincer l'oignon, éplucher et couper les carottes en rondelles. Rincer les lentilles.","Faire revenir l'oignon 3 min à feu moyen dans une casserole avec un filet d'huile.","Ajouter les carottes, les lentilles, le cumin, le cube et 1,2 l d'eau. Porter à ébullition puis cuire 25 min à feu doux, jusqu'à ce que les carottes soient tendres.","Mixer finement, ajouter la crème et rectifier le sel. Servir avec le pain et le comté."],"buddha-bowl-pois-chiches-patate-douce":["Préchauffer le four à 210 °C. Éplucher la patate douce et la couper en cubes de 2 cm. Rincer, égoutter et sécher les pois chiches.","Étaler patate douce et pois chiches sur une plaque avec l'huile, le paprika et du sel. Rôtir 30 min à 210 °C en remuant à mi-cuisson, jusqu'à ce que les pois chiches soient croustillants.","Cuire le quinoa 12 min (ou le boulgour 10 min) dans deux fois son volume d'eau salée, puis l'égoutter.","Émincer finement le chou rouge, couper l'avocat en tranches. Mélanger le yaourt avec le jus du citron et une pincée de sel.","Composer les bols : céréale, légumes rôtis, chou, avocat, et napper de yaourt citronné."],"pates-pois-chiches-romarin":["Émincer l'oignon, hacher l'ail. Rincer les pois chiches.","Chauffer l'huile à feu moyen dans une grande casserole. Faire revenir l'oignon, l'ail et le romarin 3 min.","Ajouter les pois chiches, le coulis, le cube et 80 cl d'eau. Écraser un tiers des pois chiches à la fourchette et porter à ébullition.","Verser les pâtes directement dans la casserole et cuire 10 à 12 min à feu moyen en remuant souvent, jusqu'à ce qu'elles soient tendres et la sauce crémeuse (ajouter un peu d'eau si besoin).","Servir avec le parmesan râpé et un filet d'huile d'olive."],"tofu-saute-legumes-nouilles":["Cuire les nouilles 3 à 4 min dans l'eau bouillante (temps du paquet), les égoutter et les rincer à l'eau froide.","Égoutter et éponger le tofu, le couper en cubes. Le dorer 8 min à feu moyen-vif dans l'huile, en le retournant, jusqu'à ce qu'il soit doré de tous les côtés. Réserver.","Couper le brocoli en petites fleurettes, la carotte et le poivron en lanières, hacher l'ail. Les faire sauter 5 min à feu vif dans la même poêle.","Ajouter le tofu, les nouilles, la sauce soja et le miel, mélanger 2 min à feu vif et servir."],"salade-pois-chiches-concombre-feta":["Rincer et égoutter les pois chiches.","Couper le concombre, les tomates et la feta en dés, émincer finement l'oignon rouge.","Mélanger le jus du citron, l'huile, l'origan et une pincée de sel.","Mélanger tous les ingrédients avec la sauce et les olives, laisser reposer 10 min au frais pour que les saveurs se mêlent."],"gnocchis-poeles-tomate-mozzarella":["Chauffer l'huile à feu moyen-vif dans une grande poêle. Dorer les gnocchis 6 à 8 min en les remuant, jusqu'à ce qu'ils soient croustillants.","Ajouter l'ail haché, puis le coulis, saler et laisser réduire 5 min à feu doux.","Répartir la mozzarella en morceaux, couvrir et laisser fondre 2 min à feu doux.","Parsemer de basilic ciselé et servir."],"pates-pesto-courgettes":["Cuire les pâtes 9 à 11 min dans une grande casserole d'eau bouillante salée (temps du paquet).","Faire griller les pignons 2 min à sec à feu moyen, en remuant, puis les réserver.","Chauffer l'huile à feu vif et faire sauter les courgettes en dés 6 min, jusqu'à ce qu'elles soient dorées. Ajouter les tomates cerises coupées en deux 1 min.","Égoutter les pâtes en gardant un peu d'eau de cuisson. Les mélanger avec les légumes, le pesto et 2 cuillères d'eau de cuisson. Parsemer de parmesan et de pignons."],"risotto-champignons":["Porter 1 litre d'eau à frémissement avec les 2 cubes de bouillon et le garder chaud à feu doux. Émincer l'échalote et trancher les champignons.","Faire fondre la moitié du beurre à feu moyen dans une sauteuse. Faire revenir l'échalote 2 min, ajouter le riz et le nacrer 2 min en remuant, jusqu'à ce que les grains deviennent translucides.","Verser le vin et remuer jusqu'à ce qu'il soit absorbé.","Ajouter le bouillon chaud louche par louche, en remuant souvent et en attendant que chaque louche soit absorbée, pendant 18 min : le riz doit être tendre mais encore légèrement ferme au centre.","Pendant ce temps, faire sauter les champignons 6 min à feu vif dans une poêle avec un filet d'huile, saler.","Hors du feu, ajouter les champignons, le parmesan et le reste du beurre, mélanger vivement et laisser reposer 2 min à couvert. Parsemer de persil."],"gratin-courgettes-chevre":["Préchauffer le four à 200 °C. Cuire le riz 11 min dans l'eau bouillante salée et l'égoutter.","Couper les courgettes en rondelles. Les faire revenir 8 min à feu moyen dans l'huile avec l'ail haché, jusqu'à ce qu'elles aient rendu leur eau. Saler.","Mettre les courgettes dans un plat. Battre les œufs, la crème et le thym, saler, verser dessus.","Couvrir de rondelles de chèvre et cuire 25 min à 200 °C, jusqu'à ce que le dessus soit doré et l'appareil pris. Servir avec le riz."],"tarte-feuilletee-tomate-chevre":["Préchauffer le four à 200 °C. Dérouler la pâte sur une plaque avec son papier, la piquer à la fourchette et la badigeonner de moutarde.","Couper les tomates en rondelles et les éponger sur du papier absorbant pour que la pâte ne détrempe pas.","Couvrir la pâte de rondelles de tomate et de chèvre, parsemer d'herbes, saler légèrement et arroser d'huile.","Cuire 30 min à 200 °C, jusqu'à ce que la pâte soit bien dorée et gonflée sur les bords. Servir avec la salade."],"halloumi-grille-legumes-rotis":["Préchauffer le four à 210 °C. Couper l'aubergine, la courgette, le poivron et l'oignon en morceaux de 2 cm.","Étaler les légumes sur une plaque avec l'huile, les herbes et du sel. Rôtir 30 min à 210 °C en remuant à mi-cuisson.","Cuire le boulgour 10 min dans deux fois son volume d'eau salée, puis l'égoutter.","Couper l'halloumi en tranches d'1 cm et les griller 2 min de chaque côté dans une poêle sèche à feu moyen-vif, jusqu'à ce qu'elles soient dorées.","Servir les légumes, le boulgour et l'halloumi avec un trait de citron."],"pizza-maison-legumes":["Préchauffer le four à 240 °C. Étaler les pâtes sur deux plaques avec leur papier.","Émincer les champignons et le poivron. Couper la mozzarella en tranches.","Napper les pâtes de coulis en laissant 1 cm de bord, ajouter les champignons, le poivron, la mozzarella, les olives et l'origan, puis un filet d'huile.","Cuire 12 à 15 min à 240 °C, jusqu'à ce que la pâte soit dorée et croustillante et le fromage fondu. Servir avec la salade."],"gratin-dauphinois-salade":["Préchauffer le four à 160 °C. Frotter un plat à gratin avec la gousse d'ail coupée, puis le beurrer.","Éplucher les pommes de terre et les trancher finement (3 mm), sans les rincer : leur amidon épaissit la sauce.","Les mettre dans une casserole avec le lait, du sel et la muscade. Porter à frémissement et cuire 10 min à feu doux en remuant délicatement.","Verser dans le plat, ajouter la crème et cuire 1 h à 160 °C, jusqu'à ce que le dessus soit doré et que la pointe d'un couteau traverse les pommes de terre sans résistance.","Laisser reposer 10 min et servir avec la salade."],"veloute-butternut-tartines-chevre":["Éplucher la courge, retirer les graines et la couper en cubes. Émincer l'oignon.","Faire revenir l'oignon 3 min à feu moyen dans une casserole avec un filet d'huile. Ajouter la courge, le cube et de l'eau à hauteur. Cuire 25 min à feu doux, jusqu'à ce que la courge s'écrase facilement.","Mixer finement avec la crème et la muscade, rectifier le sel.","Préchauffer le four en position gril. Garnir les tranches de pain de chèvre et d'un filet de miel, et gratiner 5 min. Servir avec le velouté."],"lasagnes-epinards-ricotta":["Préchauffer le four à 180 °C.","Chauffer l'huile à feu moyen et faire tomber les épinards avec l'ail haché 5 min. Les égoutter en les pressant bien, les hacher grossièrement.","Mélanger les épinards avec la ricotta, la muscade et du sel.","Dans un plat, alterner coulis, feuilles de lasagne et mélange épinards-ricotta, en finissant par une couche de coulis.","Couvrir de mozzarella en tranches et de parmesan. Cuire 40 min à 180 °C, jusqu'à ce que le dessus soit doré. Laisser reposer 10 min avant de couper."],"salade-chevre-chaud":["Préchauffer le four à 200 °C. Couper la baguette en tranches et poser une rondelle de chèvre sur chacune.","Gratiner 8 min à 200 °C, jusqu'à ce que le chèvre soit fondant et doré.","Préparer la vinaigrette avec le vinaigre, l'huile, le miel et du sel.","Assaisonner la salade, ajouter les tomates cerises coupées en deux et les noix, et servir avec les toasts bien chauds."],"aubergines-courgettes-gratinees-mozzarella":["Préchauffer le four à 200 °C. Couper l'aubergine et la courgette en tranches de 5 mm.","Étaler les tranches sur des plaques, les badigeonner d'huile, saler et les rôtir 15 min à 200 °C, jusqu'à ce qu'elles soient tendres.","Dans un plat, alterner légumes, coulis et mozzarella en tranches, et finir par le parmesan.","Cuire 20 min à 200 °C, jusqu'à ce que le dessus soit gratiné. Parsemer de basilic et servir avec le pain."],"veloute-potimarron-croutons":["Laver le potimarron (la peau se mange), l'épépiner et le couper en morceaux. Éplucher la pomme de terre et l'oignon et les couper en morceaux.","Mettre le tout dans une casserole avec le cube et de l'eau à hauteur. Porter à ébullition puis cuire 25 min à feu doux, jusqu'à ce que le potimarron soit tendre.","Mixer finement avec la crème et la muscade, rectifier le sel.","Servir avec les croûtons et le fromage."],"patates-douces-farcies-feta-epinards":["Préchauffer le four à 200 °C. Laver les patates douces, les piquer à la fourchette et les cuire entières 45 min à 200 °C, jusqu'à ce que la pointe d'un couteau les traverse facilement.","Quelques minutes avant la fin, chauffer l'huile à feu moyen et faire tomber les épinards avec l'ail haché 3 min. Saler.","Fendre les patates douces en deux et écraser légèrement la chair à la fourchette.","Garnir d'épinards, de feta émiettée, d'une cuillère de yaourt et de graines."],"pommes-de-terre-raclette-salade":["Laver les pommes de terre et les cuire entières 25 min dans l'eau salée, départ eau froide, jusqu'à ce qu'elles soient tendres.","Préchauffer le four en position gril.","Couper les pommes de terre en deux, les poser dans un plat, face coupée vers le haut, et les couvrir de raclette.","Gratiner 5 min sous le gril, jusqu'à ce que le fromage bouillonne. Servir avec les cornichons, l'oignon rouge émincé, la salade et la charcuterie pour qui en veut."]}$etapes$::jsonb) loop
    select id into rid from public.recipes where household_id is null and slug = r.slug;
    if rid is null or exists (select 1 from public.recipe_versions where recipe_id = rid and change_note = 'Étapes détaillées : durées, intensité du feu, température du four, repères de cuisson.') then
      continue;
    end if;
    select v.* into cv from public.recipe_versions v join public.recipes c on c.current_version_id = v.id where c.id = rid;
    p := jsonb_build_object(
      'name', cv.name, 'description', cv.description, 'servings', cv.servings, 'prep_min', cv.prep_min, 'cook_min', cv.cook_min,
      'rest_min', cv.rest_min, 'difficulty', cv.difficulty, 'meal_types', to_jsonb(cv.meal_types), 'main_protein', cv.main_protein,
      'cuisine', cv.cuisine, 'seasons', to_jsonb(cv.seasons), 'tags', to_jsonb(cv.tags), 'status', cv.status, 'steps', r.steps,
      'ingredients', (select jsonb_agg(jsonb_build_object('slug', i.slug, 'label', ri.label, 'quantity', ri.quantity, 'unit', ri.unit,
        'base_quantity', ri.base_quantity, 'base_unit', ri.base_unit, 'optional', ri.optional, 'scale', ri.scale_mode) order by ri.position)
        from public.recipe_ingredients ri left join public.ingredients i on i.id = ri.ingredient_id where ri.version_id = cv.id));
    perform private.insert_recipe_version(rid, p, 'Étapes détaillées : durées, intensité du feu, température du four, repères de cuisson.');
    update public.recipe_versions set created_by = null where recipe_id = rid and change_note = 'Étapes détaillées : durées, intensité du feu, température du four, repères de cuisson.';
  end loop;
end
$do$;
